export type AgentTest = {
  id: string;
  agent_id: string;
  name: string;
  kind: "simulated" | "replay";
  /** `owner`: written by hand. `call`: made from a real call. `assist`: Build with AI. */
  origin: "owner" | "call" | "assist";
  /** When the owner last changed the test by hand. An edited suggestion is kept when tests are suggested again. */
  edited_at: string | null;
  goal: string | null;
  persona: string | null;
  language: "en" | "es";
  call_time: AgentTestCallTime;
  pass_rules: Array<AgentTestPassRule>;
  caller_turns: Array<string> | null;
  source_call_id: string | null;
  created_at: string;
  updated_at: string;
};

/** The local time (in the agent's time zone) the simulated call happens at, e.g. to test an after-hours caller. Null: the next weekday at 10:00. */
export type AgentTestCallTime = {
  weekday: "mon" | "tue" | "wed" | "thu" | "fri" | "sat" | "sun";
  time: string;
} | null;

export type AgentTestPassRule = {
  type: "outcome";
  /** The call passes when it ends with any of these outcomes */
  outcomes: Array<"booked" | "message_taken" | "urgent_escalated" | "transferred" | "spam" | "no_action" | "info_provided">;
} | {
  type: "judge";
  /** A plain rule a judge checks, e.g. 'Offers a Tuesday time' */
  text: string;
};

export type AgentTestInput = {
  /** Defaults to `"simulated"`. */
  kind?: "simulated" | "replay";
  name: string;
  /** Simulated tests: what the caller wants, e.g. 'Book a cleaning next Tuesday' */
  goal?: string | null;
  /** Simulated tests: who the caller is and how they talk, e.g. 'In a hurry, terse' */
  persona?: string | null;
  /** Defaults to `"en"`. */
  language?: "en" | "es";
  call_time?: AgentTestCallTime;
  /** Defaults to `[]`. */
  pass_rules?: Array<AgentTestPassRule>;
  /** Replay tests: what the caller said, in order */
  caller_turns?: Array<string> | null;
};

export type AgentTestUpdate = {
  name?: string;
  /** Simulated tests: what the caller wants, e.g. 'Book a cleaning next Tuesday' */
  goal?: string | null;
  /** Simulated tests: who the caller is and how they talk, e.g. 'In a hurry, terse' */
  persona?: string | null;
  language?: "en" | "es";
  call_time?: AgentTestCallTime;
  pass_rules?: Array<AgentTestPassRule>;
  /** Replay tests: what the caller said, in order */
  caller_turns?: Array<string> | null;
};

export type AgentTestRun = {
  id: string;
  agent_id: string;
  purpose: "manual" | "publish_check";
  target: "live" | "draft" | "changes";
  status: "running" | "done" | "cancelled";
  created_at: string;
  finished_at: string | null;
  /** False: the test runner hasn't checked in, so queued tests are waiting */
  runner_online: boolean;
  counts: {
    total: number;
    queued: number;
    running: number;
    passed: number;
    failed: number;
    unclear: number;
    other: number;
  };
  comparison: AgentTestComparison;
  results: Array<{
    test_id: string;
    live?: AgentTestResult;
    candidate?: AgentTestResult;
  }>;
};

/** The candidate against live, when the run tested a candidate */
export type AgentTestComparison = {
  worse: number;
  better: number;
  same: number;
  /** Tests without a scored result on both sides */
  unknown: number;
  /** Of `unknown`, tests scored on live with no score on the new version (an error, a timeout or a skip). `block` refuses a publish while this is above 0. */
  not_run: number;
} | null;

export type AgentTestResult = {
  id: string;
  test_id: string;
  name: string;
  side: "live" | "candidate";
  status: "queued" | "running" | "passed" | "failed" | "unclear" | "error" | "skipped";
  checks: Array<AgentTestCheck>;
  call: {
    transcript: Array<{
      role: "agent" | "caller";
      text: string;
    }>;
    tool_calls: Array<{
      name: string;
      args: {
        [key: string]: unknown;
      };
      ok: boolean;
    }>;
    outcome: string | null;
    ended_by: string | null;
    seconds: number;
  } | null;
  error: string | null;
  /** A current live result from an earlier run, not run again for this check */
  reused: boolean;
  finished_at: string | null;
};

