/** Query parameters for `GET /v1/calls`. */
export type CallListParams = {
  /** Only calls that started at or after this time (inclusive) */
  from?: string;
  /** Only calls that started before this time (exclusive) */
  to?: string;
  outcome?: "booked" | "message_taken" | "urgent_escalated" | "transferred" | "spam" | "blocked" | "cap_reached" | "no_action" | "info_provided";
  kind?: "live" | "test";
  channel?: "phone" | "web_chat";
  /** Only web chats that came through this chat widget */
  widget_id?: string;
  urgency?: "low" | "normal" | "high";
  /** Only calls still in progress, or only finished ones */
  status?: "in_progress" | "completed";
  phone_number_id?: string;
  /** Only calls from this phone number (`from_number`), in any format: +15555550123, (555) 555-0123 and 555.555.0123 all match. Bare 10-digit numbers are read as North American. */
  caller_phone?: string;
  /** Only calls handled by this agent (any of its deployments) */
  agent_id?: string;
  language?: "en" | "es";
  /** Only calls the caller hung up right after the greeting (under 20 seconds, still on the first step), or only the rest */
  hung_up_early?: "true" | "false";
  /** Only calls that started outside (or inside) the hours of the calendar their agent books into. Calls of agents without set hours match neither. */
  after_hours?: "true" | "false";
  /** Only calls with this reason (`extracted.reason`, ignoring case) */
  reason?: string;
  /** Only calls the caller hung up partway through a booking, a message, or either (`any`) */
  unfinished?: "booking" | "message" | "any";
  /** Only each person's first conversation with the business, or only calls from people who'd been in touch before. Calls not linked to a person match neither. */
  first_call?: "true" | "false";
  /** Only calls the post-call review flagged a line in, or only the rest */
  flagged?: "true" | "false";
  /** Only calls where the booking calendar or CRM couldn't be reached, or only the rest */
  calendar_error?: "true" | "false";
  /** Only calls that started on this weekday (0 Sunday to 6 Saturday) in `time_zone` */
  weekday?: number | null;
  /** Only calls that started in this hour of the day (0 to 23) in `time_zone` */
  hour?: number | null;
  /**
   * IANA zone `weekday` and `hour` are read in
   *
   * Defaults to `"UTC"`.
   */
  time_zone?: string;
  /** Only calls from people with more than one call among those the other filters pick by date, kind, channel, agent and number (the Analytics page's callers who called more than once) */
  repeat_caller?: "true";
  workflow_version_id?: string;
  /** Only calls that entered this workflow step */
  step?: string;
  /** Only calls that ended on this workflow step */
  last_step?: string;
  /** Only calls judged this way against their agent's success criteria */
  success?: "passed" | "failed" | "unclear";
  /** Defaults to `50`. */
  limit?: number;
  /** `next_cursor` from the previous page */
  cursor?: string;
};

